L628: parse_block_signal_params (const char* optarg, bool block)
L629: {
L630:   char signame[SIG2STR_MAX];
L631:   char *opt_sig;
L632:   char *optarg_writable;
L633:   if (! optarg)
L634:     {
L635:       /* without an argument, reset all signals.  */
L636:       sigfillset (block ? &block_signals : &unblock_signals);
L637:       sigemptyset (block ? &unblock_signals : &block_signals);
L638:     }
L639:   else if (! sig_mask_changed)
L640:     {
L641:       /* Initialize the sets.  */
L642:       sigemptyset (&block_signals);
L643:       sigemptyset (&unblock_signals);
L644:     }
L645: 
L646:   sig_mask_changed = true;
L647: 
L648:   if (! optarg)
L649:     return;
