L651:   optarg_writable = xstrdup (optarg);
L652:   opt_sig = strtok (optarg_writable, ",");
L653:   while (opt_sig)
L654:     {
L655:       int signum = operand2sig (opt_sig, signame);
L656:       /* operand2sig accepts signal 0 (EXIT) - but we reject it.  */
L657:       if (signum == 0)
